insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000000b1001', '00000000-0000-4000-8000-0000000b0101', 1, 'published', null, 'EUR', $json${"title":"Cómo funciona","cards":[{"icon":"calendar","title":"1. Creas la inmersión.","body":"Hora, punto de inmersión y tipo. Los datos del punto ya están cargados: profundidad máxima, tiempo habitual, visibilidad, vida marina."},{"icon":"qr","title":"2. El buceador escanea tu QR.","body":"Elige la inmersión de hoy y la guarda. Su logbook queda relleno sin escribir nada."},{"icon":"users","title":"3. A ti te queda el registro.","body":"Cada buceador que guarda una inmersión entra en tu lista, con todo lo que ha hecho contigo."}],"screens":[{"screen":"create-activity"},{"screen":"qr-activity"},{"screen":"crm-list"}]}$json$::jsonb);
