insert into public.segment (id, tenant_id, key, name, description, value_prop, icp, disqualifiers, buying_process, deal_size, sales_cycle, position, status, icon, image) values ('00000000-0000-4000-8000-0000005e0001', '00000000-0000-4000-8000-000000000e01', 'bodas', 'Bodas', 'Novios que celebran su boda y las fincas/salas que la acogen.', 'El banquete se convierte en algo que los invitados hacen, no que miran: recuerdos compartidos sin descargar ninguna app.', '- Bodas de 100+ invitados
insert into public.segment (id, tenant_id, key, name, description, value_prop, icp, disqualifiers, buying_process, deal_size, sales_cycle, position, status, icon, image, proposal) values ('00000000-0000-4000-8000-0000005e0002', '00000000-0000-4000-8000-000000000e01', 'ocio-nocturno', 'Locales de ocio nocturno', 'Discotecas, pubs y salas con programación semanal.', 'Más tiempo en pista, más consumo y clientes que vuelven: el público interactúa con la pantalla y genera contenido para redes.', '- Aforo 300+ y pantallas en sala
insert into public.segment (id, tenant_id, key, name, description, value_prop, icp, disqualifiers, buying_process, deal_size, sales_cycle, position, status, icon, image, notice) values ('00000000-0000-4000-8000-0000005e0003', '00000000-0000-4000-8000-000000000e01', 'conciertos', 'Conciertos', 'Promotoras y salas de conciertos (giras y fechas sueltas).', 'Interacción del público con el artista y datos de asistentes para la promotora y las marcas.', '- Salas de 500+ personas con pantalla
insert into public.segment (id, tenant_id, key, name, description, value_prop, icp, disqualifiers, buying_process, deal_size, sales_cycle, position, status, icon, image, notice) values ('00000000-0000-4000-8000-0000005e0004', '00000000-0000-4000-8000-000000000e01', 'festivales', 'Festivales', 'Festivales de música con patrocinadores y zonas comunes.', 'Activaciones de marca medibles y experiencia en zonas comunes y entre conciertos.', '- 5.000+ asistentes
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0001', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'novios', 'Novios', 'decisor', 'Una boda que los invitados recuerden y en la que todos participen.', 'Tiempos muertos en el banquete, mesas que no se mezclan, invitados mayores que no participan.', null, '{"precio","tiempo"}', 'Reunión o videollamada con los DOS. Haz la demo en su propio móvil: que envíen una kiss-cam y la vean en pantalla.', 'Tecnicismos y hablar de "plataforma". Hablar solo con uno de los dos.', 'Si les encanta, lo enseñan a la finca y a sus amigos que se casan (referidos).', 'Si no lo entienden en 2 minutos, lo descartan como "otra cosa más que pagar".', 1024);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0002', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'coordinadora-finca', 'Coordinador/a de la finca', 'guardian', 'Que el día salga perfecto y sin problemas técnicos.', 'Proveedores externos que llegan tarde, ocupan espacio o fallan.', null, '{"desconfianza","ya_tengo_proveedor"}', 'Preséntate antes del evento, pásale la ficha técnica y ofrece montaje sin trabajo para su equipo.', 'Saltártela hablando solo con los novios: lo vivirá como una imposición.', 'Si confía en ti, te mete en su lista de proveedores recomendados (canal recurrente).', 'Puede decir "aquí no se puede montar" y tumbarlo en un minuto.', 2048);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0003', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'gerente-finca', 'Gerente de la finca/sala', 'decisor', 'Llenar fechas y diferenciarse de las fincas de alrededor.', 'Competencia en precio, bodas que se pierden contra otra finca.', 'Bodas al año, ticket medio por boda.', '{"precio","no_lo_necesito"}', 'Con números: "si ganas 3 bodas más al año por diferenciación, Enjoy se paga varias veces". Propón una boda piloto.', 'Venderle a los novios saltándote a la finca.', 'Lo incluye en su pack de bodas: volumen recurrente.', 'Prohíbe proveedores externos o exige exclusividad con los suyos.', 3072);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0004', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'dj-boda', 'DJ de la boda', 'influenciador', 'Que la pista se llene y quedar como el que lo hizo posible.', 'Que otro proveedor le quite protagonismo o le complique el directo.', null, '{"ya_tengo_proveedor","desconfianza"}', 'Plantéalo como SU herramienta: él lanza los retos desde el micro. Llámale antes del evento.', 'Venderlo como "algo que anima la boda" (eso es su trabajo).', 'Lo anima en directo y dispara la participación.', 'No cede pantalla ni micro, o lo ignora durante la fiesta.', 4096);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0005', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'wedding-planner', 'Wedding planner', 'campeon', 'Sorprender a sus novios y diferenciar su servicio.', 'Repetir las mismas ideas en todas las bodas.', null, '{"comparar"}', 'Propón un acuerdo de recomendación y una demo para su cartera de novios.', 'Tratarle como un intermediario más.', 'Prescribe a varias parejas por temporada.', 'Si una boda sale mal, no te vuelve a recomendar.', 5120);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0006', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0002', 'propietario-local', 'Propietario/gerente del local', 'decisor', 'Más consumo por cliente y que vuelvan cada semana.', 'Noches flojas entre semana, competencia de otros locales.', 'Caja por noche, ocupación, repetición.', '{"precio","no_lo_necesito"}', 'Visita por la tarde (nunca en plena noche) con datos de otro local y una demo en su pantalla.', 'Llamarle un sábado por la noche; hablar de "experiencia" sin hablar de caja.', 'Decide rápido si ve el retorno.', 'El precio mensual si no ve el retorno en caja.', 6144);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0007', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0002', 'rrpp-marketing', 'RRPP / marketing del local', 'campeon', 'Contenido para redes y base de datos de clientes.', 'No saber quién viene ni cómo volver a llamarlos.', 'Seguidores, asistentes a eventos, base de datos.', '{"no_decido_yo"}', 'Enséñale el contenido que genera una noche y la captación de datos de asistentes.', 'Darle todo el mérito al dueño delante de él.', 'Lo defiende internamente y lo usa cada semana.', 'Si no lo ve útil para redes, no lo empuja.', 7168);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0008', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0002', 'dj-residente', 'DJ residente', 'guardian', 'Control total de la pista y de la sesión.', 'Interrupciones y cosas que cortan el ritmo.', null, '{"desconfianza"}', 'Habla con él ANTES de la demo con el dueño; que decida en qué momentos de la sesión se lanza cada reto.', 'Imponérselo a través del dueño.', 'Lo integra en la sesión y lo convierte en parte del show.', 'Lo ignora o lo sabotea: sin él no hay participación.', 8192);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0009', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0002', 'marca-bebidas', 'Marca de bebidas patrocinadora', 'pagador', 'Visibilidad y activaciones medibles en el local.', 'Activaciones caras sin datos de resultado.', 'Impactos, participación, leads.', '{"comparar","precio"}', 'Propón una activación cofinanciada con el local: retos patrocinados con su marca en pantalla.', 'Pedirle dinero sin enseñar métricas.', 'Paga parte (o todo) el coste para el local.', 'Si no hay datos, no repite.', 9216);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0010', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0003', 'promotor', 'Promotor/a', 'decisor', 'Una experiencia diferencial y más ingresos por patrocinio.', 'Márgenes ajustados y no conocer a su público.', 'Entradas vendidas, ingresos por patrocinio.', '{"precio","tiempo"}', 'Ofrece un piloto en una fecha con una marca que lo cofinancie.', 'Pedirle compromiso para toda la gira de entrada.', 'Lo extiende a la gira y a otros artistas.', 'Si no hay patrocinio, el precio lo frena.', 10240);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0011', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0003', 'manager-artista', 'Manager del artista', 'guardian', 'Proteger la imagen del artista y el show.', 'Cosas que distraen o mensajes inapropiados en pantalla.', null, '{"desconfianza"}', 'Enséñale la moderación previa y el control total de lo que sale en pantalla.', 'Que se entere por el promotor el día del concierto.', 'Si al artista le gusta, lo pide en otras fechas.', 'Veto directo: "esto no sale en nuestro show".', 11264);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0012', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0003', 'marca-patrocinadora', 'Marca patrocinadora', 'pagador', 'Visibilidad entre el público objetivo con métricas.', 'Logos en una lona que nadie mira.', 'Impactos, participación, leads.', '{"comparar"}', 'Propuesta de activación con KPIs: participaciones, datos captados, contenido.', 'Venderle "visibilidad" sin números.', 'Paga la activación.', 'Sin datos, no renueva.', 12288);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0013', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0004', 'director-festival', 'Dirección del festival', 'decisor', 'Diferenciar el festival y aumentar ingresos.', 'Presupuesto cerrado meses antes.', 'Asistentes, ingresos, prensa.', '{"tiempo","precio"}', 'Llega al menos 6 meses antes de la edición con un caso y una propuesta para patrocinios.', 'Llegar con la temporada empezada.', 'Lo convierte en seña de identidad del festival.', 'Si llega tarde, no hay presupuesto.', 13312);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0014', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0004', 'responsable-patrocinios', 'Responsable de patrocinios', 'campeon', 'Tener activaciones nuevas y medibles que vender a las marcas.', 'Marcas que no renuevan por falta de resultados.', 'Ingresos por patrocinio, renovaciones.', '{"no_decido_yo"}', 'Dale un dossier pensado para que él se lo venda a sus marcas (con métricas de ejemplo).', 'Competir con sus propios patrocinios.', 'Lo vende a varias marcas: multiplica el acuerdo.', 'Si no ve cómo venderlo, no lo mueve.', 14336);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0015', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0004', 'produccion-tecnica', 'Producción técnica', 'guardian', 'Que nada técnico falle en directo.', 'Conectividad, pantallas compartidas, riesgos.', null, '{"desconfianza"}', 'Ficha técnica, requisitos de red y una prueba previa en el recinto.', 'Prometer cosas técnicas sin haber visto el recinto.', 'Facilita el montaje y la red.', 'Veto técnico: "no hay red", "la pantalla no es vuestra".', 15360);
