insert into public.share_link (id, dossier_id, token, is_active, expires_at) values ('00000000-0000-4000-8000-0000000b0d71', '00000000-0000-4000-8000-0000000b0d51', 'demo-oquea-ko-5Rt8', true, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0001', '00000000-0000-4000-8000-000000000e01', null, 'empresa-pitch', 'pitch', 'pitch_demo', null, '{}', 'Enjoy en una frase', 'Enjoy convierte cada momento de la celebración en algo que los invitados **hacen**, no que **miran**: kiss-cam, dedicatorias y retos desde su propio móvil, sin descargar nada.', 'Primeros 30 segundos de cualquier conversación (novios o sala).', 'Diferencia frente al fotomatón o el DJ: la participación es el producto.', $json$[]$json$::jsonb, 1024, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0002', '00000000-0000-4000-8000-000000000e01', null, 'empresa-icp', 'fit', 'prospeccion', null, '{"bodas"}', 'Cliente ideal (y cuándo no)', '- **Novios** con 100+ invitados que quieren una boda "diferente" y temen los tiempos muertos.
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0003', '00000000-0000-4000-8000-000000000e01', null, 'empresa-apertura', 'script', 'primer_contacto', null, '{"bodas"}', 'Apertura de la reunión', 'Hola {prospect}, gracias por el rato. Antes de enseñarte nada: ¿qué es lo que más os importa que recuerden vuestros invitados de {company}?', 'Al empezar la llamada o la visita.', 'Abre con su objetivo, no con tu producto: lo que digan es tu guion para el resto de la reunión.', $json$[]$json$::jsonb, 3072, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0004', '00000000-0000-4000-8000-000000000e01', null, 'empresa-descubrir-1', 'discovery', 'descubrimiento', null, '{"bodas"}', '¿Qué te preocupa que pase en el banquete?', 'Escucha si aparecen: tiempos muertos, mesas que no se mezclan, invitados mayores que no participan. Cada respuesta se conecta con un módulo.', null, null, $json$[]$json$::jsonb, 4096, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0005', '00000000-0000-4000-8000-000000000e01', null, 'empresa-descubrir-2', 'discovery', 'descubrimiento', 'no_decido_yo', '{}', '¿Quién más decide?', 'Pregunta pronto si deciden ambos novios, la familia o el coordinador de la sala. Evita la objeción "lo tengo que consultar" al final.', null, null, $json$[]$json$::jsonb, 5120, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0006', '00000000-0000-4000-8000-000000000e01', null, 'empresa-obj-precio', 'objection', 'objeciones', 'precio', '{}', '"Es caro"', 'No justifiques el precio. Pregunta con qué lo están comparando y vuelve a **lo que les preocupaba** del banquete (lo que dijeron en el descubrimiento). Enjoy cuesta menos por invitado que una ronda de chupitos.', 'Cuando aparece el precio antes de que hayan visto el valor.', '"Caro" casi nunca es el número: es valor no percibido todavía.', $json$[{"source":"cerebro","id":707,"title":"El cliente dice 'caro' porque traduce precio a horas trabajadas, no a valor","creator":"Alfonso y Cristian","url":"https://www.youtube.com/watch?v=ksjIkdhPxDU&t=5790"},{"source":"cerebro","id":342,"title":"El dinero nunca es el problema real","creator":"Alfonso y Cristian","url":"https://www.tiktok.com/@alfonsoychristian"}]$json$::jsonb, 6144, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0007', '00000000-0000-4000-8000-000000000e01', null, 'empresa-obj-pensar', 'objection', 'objeciones', 'tiempo', '{}', '"Nos lo pensamos"', 'Pregunta qué parte quieren pensar: ¿precio, fecha o si encaja con su boda? Propón dejar la fecha **reservada 7 días sin compromiso** y agenda la llamada en ese momento.', null, null, $json$[]$json$::jsonb, 7168, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0008', '00000000-0000-4000-8000-000000000e01', null, 'empresa-cierre', 'script', 'cierre', null, '{"bodas"}', 'Cierre con fecha', '¿Os parece que dejemos reservada la fecha de vuestra boda y el jueves te llamo a las 18:00 para cerrar los detalles con vosotros dos?', null, 'Una sola fecha concreta: un menú de opciones hace trabajar al otro y retrasa la decisión.', $json$[]$json$::jsonb, 8192, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0009', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-pitch', 'pitch', 'pitch_demo', null, '{}', 'Kiss-cam, dedicatorias y retos: el banquete se convierte en juego', 'Cada invitado participa desde su móvil (sin app) y lo que envía sale en la pantalla en directo. Nadie se queda mirando el plato.', 'Cuando han mencionado tiempos muertos o mesas que no se mezclan.', null, $json$[]$json$::jsonb, 9216, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0010', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-fit', 'fit', 'descubrimiento', null, '{"bodas"}', 'Encaja mejor en…', 'Bodas de 100+ invitados, con pantalla o proyector en el salón. Con menos de 60 invitados, ofrece solo dedicatorias.', null, null, $json$[]$json$::jsonb, 10240, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0011', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-demo', 'tip', 'pitch_demo', null, '{}', 'Enseña el móvil, no la pantalla', 'En la demo, pásale TU móvil con la kiss-cam abierta y que envíe algo: lo ve aparecer en la vista previa del dossier. Vender la experiencia > describirla.', null, null, $json$[]$json$::jsonb, 11264, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0012', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-obj-mayores', 'objection', 'objeciones', 'no_lo_necesito', '{}', '"Mis invitados son mayores, no van a participar"', 'Las dedicatorias son el módulo que más usan los mayores: escribir unas palabras a los novios. Los nietos les ayudan con el móvil y eso también es parte del recuerdo.', null, null, $json$[]$json$::jsonb, 12288, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0013', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-prueba', 'proof', 'pitch_demo', null, '{}', 'Participación media 92 %', 'Dato de ejemplo (sustituir por el real de Enjoy): 9 de cada 10 invitados envían al menos una kiss-cam o dedicatoria.', null, null, $json$[]$json$::jsonb, 13312, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0014', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'exp-upsell', 'monetization', 'negociacion', null, '{}', 'Pack Kiss-cam + Retos', 'Vende las experiencias en pack (no sueltas): el pack completo sube el ticket medio ~30 % y el coste marginal es casi cero. Descuento máximo autorizado: 10 %.', null, 'El margen está en el pack; las experiencias sueltas compiten con el DJ.', $json$[]$json$::jsonb, 14336, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0015', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e103', 'loc-pitch', 'pitch', 'pitch_demo', null, '{"bodas"}', 'Un extra que vendes tú y te diferencia de la finca de al lado', 'La sala incluye Enjoy en su oferta de bodas: lo vende como propio, se queda margen y tiene un argumento que la competencia no tiene.', null, null, $json$[]$json$::jsonb, 15360, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0016', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e103', 'loc-discovery', 'discovery', 'descubrimiento', null, '{"bodas"}', '¿Cuántas bodas hacéis al año y cuántas perdéis contra otra sala?', 'Si pierden bodas por "diferenciación", Enjoy es su argumento. Calcula con ellos: 3 bodas más al año pagan Enjoy varias veces.', null, null, $json$[]$json$::jsonb, 16384, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0017', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e103', 'loc-obj-proveedor', 'objection', 'objeciones', 'ya_tengo_proveedor', '{"bodas"}', '"Ya trabajamos con un DJ que hace cosas parecidas"', 'Enjoy no sustituye al DJ: se apoya en él (la pantalla y el micro). Propón una boda piloto con su DJ para que lo vea funcionar juntos.', null, null, $json$[]$json$::jsonb, 17408, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0018', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e103', 'loc-monet', 'monetization', 'negociacion', null, '{"bodas"}', 'Margen para la sala', 'Precio a la sala por evento + PVP recomendado a los novios. La sala decide si lo regala (diferenciación) o lo cobra (margen). Ejemplo: coste 250 €, PVP 450 €.', null, null, $json$[]$json$::jsonb, 18432, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas) values ('00000000-0000-4000-8000-0000009a0019', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e104', 'precio-presentar', 'tip', 'negociacion', 'precio', '{}', 'Presenta el precio después del valor', 'La tarjeta de precio va siempre al final del dossier. Si te piden precio al principio, da una horquilla y vuelve al descubrimiento.', null, null, $json$[]$json$::jsonb, 19456, 'official', 1, null, '{}');
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, personas, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0020', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'noche-obj-dj', 'objection', 'objeciones', 'desconfianza', '{"ocio-nocturno"}', '{"dj-residente"}', 'DJ residente: "Esto me corta la sesión"', 'Él decide cuándo se lanza cada reto: Enjoy no interrumpe, le da munición. Propón probarlo una noche en los momentos que él elija.', null, null, $json$[]$json$::jsonb, 20480, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, personas, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0021', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'noche-pitch-propietario', 'pitch', 'pitch_demo', null, '{"ocio-nocturno"}', '{"propietario-local"}', 'Para el dueño del local: más tiempo en pista, más caja', 'Cada reto en pantalla mantiene a la gente en la pista (y en la barra) 10–15 minutos más. Ejemplo para validar con datos reales del local.', null, null, $json$[]$json$::jsonb, 21504, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, personas, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0022', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-00000000e102', 'fest-patrocinios', 'monetization', 'negociacion', null, '{"festivales"}', '{"responsable-patrocinios","marca-patrocinadora"}', 'Que lo pague el patrocinador', 'En festivales, véndelo como formato de activación para las marcas: el festival no paga, cobra. Prepara métricas de ejemplo (participaciones, datos captados).', null, null, $json$[]$json$::jsonb, 22528, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, personas, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0023', '00000000-0000-4000-8000-000000000e01', null, 'seguimiento-48h', 'script', 'seguimiento', null, '{}', '{}', 'Seguimiento a las 48 h de enviar el dossier', 'Hola {prospect}, ¿pudisteis verlo juntos? Te dejo una idea concreta para {company}: [un detalle del dossier que encaje con lo que te contó]. ¿Te va bien el jueves a las 18:00 y lo cerramos?', 'Si no han respondido 48 h después de enviar el enlace.', null, $json$[]$json$::jsonb, 23552, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, personas, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0024', '00000000-0000-4000-8000-000000000e01', null, 'b2b-apertura', 'script', 'primer_contacto', null, '{"ocio-nocturno","conciertos","festivales"}', '{}', 'Apertura (locales, conciertos y festivales)', 'Hola {prospect}, gracias por el rato. Antes de enseñarte nada: ¿qué noche o qué evento os está costando más llenar en {company}, y qué habéis probado ya?', null, 'Abre con su problema de negocio (llenar, consumo, patrocinio), no con el producto.', $json$[]$json$::jsonb, 24576, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, personas, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id) values ('00000000-0000-4000-8000-0000009a0025', '00000000-0000-4000-8000-000000000e01', null, 'b2b-cierre', 'script', 'cierre', null, '{"ocio-nocturno","conciertos","festivales"}', '{}', 'Cierre con piloto', '¿Lo probamos en una noche (o una fecha) piloto? Te propongo el jueves 14: lo montamos nosotros y el viernes vemos juntos los datos de participación.', null, 'Un piloto con fecha baja el riesgo percibido y deja una decisión concreta.', $json$[]$json$::jsonb, 25600, 'official', 1, null);
insert into public.play (id, tenant_id, module_id, key, kind, stage, objection, segments, title, body, when_to_use, why_it_works, technique_refs, position, status, version, author_id, personas, about) values ('00000000-0000-4000-8000-0000009a00f1', '00000000-0000-4000-8000-000000000e01', null, 'vision', 'tip', 'mentalidad', null, '{}', 'La visión', 'La gente sale menos y, cuando sale, está con el móvil. Pelearse contra eso es perder. Enjoy no quiere que la gente mire menos el móvil: quiere que lo que haga con él pase en la sala y no en otro sitio.', null, null, $json$[]$json$::jsonb, 512, 'official', 1, null, '{}', true);
insert into public.dossier_contact (id, tenant_id, dossier_id, persona_id, name, stance, email, phone, notes, position, traits) values ('00000000-0000-4000-8000-0000000c0001', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-000000d05501', '00000000-0000-4000-8000-0000009e0001', 'Laura (novia)', 'aliado', null, null, 'Le encantó la kiss-cam en la demo.', 1024, $json${"personalidad":["expresivo"]}$json$::jsonb);
insert into public.dossier_contact (id, tenant_id, dossier_id, persona_id, name, stance, email, phone, notes, position, traits) values ('00000000-0000-4000-8000-0000000c0002', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-000000d05501', '00000000-0000-4000-8000-0000009e0002', 'Marta (coordinadora Sala X)', 'neutral', null, null, null, 2048, $json${}$json$::jsonb);
insert into public.dossier_contact (id, tenant_id, dossier_id, persona_id, name, stance, email, phone, notes, position, traits) values ('00000000-0000-4000-8000-0000000c0003', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-000000d05501', '00000000-0000-4000-8000-0000009e0004', 'DJ Toni', 'bloqueador', null, null, 'Cree que le quitamos protagonismo.', 3072, $json${"personalidad":["analitico"]}$json$::jsonb);
insert into public.win_story (id, tenant_id, author_id, title, outcome, segment_id, persona_ids, situation, play_ids, what_worked, what_failed, key_stage, objection, status, dossier_id) values ('00000000-0000-4000-8000-000000050001', '00000000-0000-4000-8000-000000000e01', null, 'Club Aurora (ejemplo)', 'won', '00000000-0000-4000-8000-0000005e0002', '{"00000000-0000-4000-8000-0000009e0006","00000000-0000-4000-8000-0000009e0008"}', $json${"personalidad":["analitico"],"region":["madrid"],"rasgos-local":["pantalla","dj"]}$json$::jsonb, '{"00000000-0000-4000-8000-0000009a0021","00000000-0000-4000-8000-0000009a0020","00000000-0000-4000-8000-0000009a0015"}', 'Hablé antes con el DJ: le enseñé que las peticiones pasan por su filtro antes de sonar y dejó de verlo como amenaza. Al dueño le llevé la caja de una noche piloto.', null, 'objeciones', 'desconfianza', 'shared', null);
insert into public.win_story (id, tenant_id, author_id, title, outcome, segment_id, persona_ids, situation, play_ids, what_worked, what_failed, key_stage, objection, status, dossier_id) values ('00000000-0000-4000-8000-000000050002', '00000000-0000-4000-8000-000000000e01', null, 'Sala Faro (ejemplo)', 'won', '00000000-0000-4000-8000-0000005e0002', '{"00000000-0000-4000-8000-0000009e0006"}', $json${"personalidad":["directo"],"region":["barcelona"],"rasgos-local":["pantalla"]}$json$::jsonb, '{"00000000-0000-4000-8000-0000009a0021","00000000-0000-4000-8000-0000009a0006","00000000-0000-4000-8000-0000009a0008"}', 'Fui directo a números: coste por noche frente a una botella más vendida. Cerró en la primera reunión.', null, 'cierre', 'precio', 'shared', null);
insert into public.win_story (id, tenant_id, author_id, title, outcome, segment_id, persona_ids, situation, play_ids, what_worked, what_failed, key_stage, objection, status, dossier_id) values ('00000000-0000-4000-8000-000000050003', '00000000-0000-4000-8000-000000000e01', null, 'Bar Nocturno (ejemplo)', 'lost', '00000000-0000-4000-8000-0000005e0002', '{"00000000-0000-4000-8000-0000009e0008"}', $json${"personalidad":["analitico"],"region":["madrid"],"rasgos-local":["dj"]}$json$::jsonb, '{"00000000-0000-4000-8000-0000009a0015"}', null, 'Presenté al dueño sin hablar antes con el DJ residente, y el DJ lo vetó.', 'objeciones', 'desconfianza', 'shared', null);
insert into public.win_story (id, tenant_id, author_id, title, outcome, segment_id, persona_ids, situation, play_ids, what_worked, what_failed, key_stage, objection, status, dossier_id) values ('00000000-0000-4000-8000-000000050004', '00000000-0000-4000-8000-000000000e01', null, 'Finca Olivar (ejemplo)', 'won', '00000000-0000-4000-8000-0000005e0001', '{"00000000-0000-4000-8000-0000009e0001","00000000-0000-4000-8000-0000009e0002"}', $json${"personalidad":["expresivo"],"region":["madrid"],"rasgos-local":["pantalla","bodas"]}$json$::jsonb, '{"00000000-0000-4000-8000-0000009a0009","00000000-0000-4000-8000-0000009a0011","00000000-0000-4000-8000-0000009a0012"}', 'La novia probó la kiss-cam en su móvil durante la reunión y se vio en la vista previa.', null, 'pitch_demo', null, 'shared', null);
